     1→package agents
     2→
     3→import (
     4→	"context"
     5→	"errors"
     6→	"fmt"
     7→	"os"
     8→	"os/exec"
     9→	"strings"
    10→	"syscall"
    11→	"time"
    12→)
    13→
    14→func init() {
    15→	if env := os.Getenv("E2E_AGENT"); env != "" && env != "cursor-cli" {
    16→		return
    17→	}
    18→	if _, err := exec.LookPath("agent"); err != nil {
    19→		return
    20→	}
    21→	Register(&CursorCLI{})
    22→}
    23→
    24→// CursorCLI implements the E2E Agent interface for the Cursor Agent CLI binary.
    25→// The CLI binary is called "agent" and uses Cursor's hooks system via
    26→// .cursor/hooks.json. It maps to the same Entire agent as Cursor IDE ("cursor").
    27→//
    28→// Key limitation: in headless (-p) mode, the beforeSubmitPrompt and stop hooks
    29→// do NOT fire. Only sessionStart, sessionEnd, and tool-use hooks fire. This
    30→// means RunPrompt-based tests won't get TurnStart/TurnEnd events. Interactive
    31→// tmux-based tests get the full lifecycle.
    32→type CursorCLI struct{}
    33→
    34→func (a *CursorCLI) Name() string               { return "cursor-cli" }
    35→func (a *CursorCLI) Binary() string             { return "agent" }
    36→func (a *CursorCLI) EntireAgent() string        { return "cursor" }
    37→func (a *CursorCLI) TimeoutMultiplier() float64 { return 1.5 }
    38→
    39→// PromptPattern returns a regex matching the Cursor CLI's TUI input prompt.
    40→// The CLI shows ">" when ready for input in interactive mode.
    41→func (a *CursorCLI) PromptPattern() string { return `>` }
    42→
    43→func (a *CursorCLI) IsTransientError(out Output, err error) bool {
    44→	if err == nil {
    45→		return false
    46→	}
    47→	if errors.Is(err, context.DeadlineExceeded) {
    48→		return true
    49→	}
    50→	combined := out.Stdout + out.Stderr
    51→	for _, p := range []string{
    52→		"overloaded",
    53→		"rate limit",
    54→		"429",
    55→		"503",
    56→		"529",
    57→		"ECONNRESET",
    58→		"ETIMEDOUT",
    59→		"server error",
    60→		"Internal Server Error",
    61→	} {
    62→		if strings.Contains(combined, p) {
    63→			return true
    64→		}
    65→	}
    66→	return false
    67→}
    68→
    69→func (a *CursorCLI) Bootstrap() error {
    70→	// The Cursor CLI authenticates via CURSOR_API_KEY env var or OAuth.
    71→	// On CI, ensure CURSOR_API_KEY is set. Locally, OAuth/keychain works.
    72→	if os.Getenv("CI") != "" && os.Getenv("CURSOR_API_KEY") == "" {
    73→		return errors.New("CURSOR_API_KEY must be set on CI for cursor-cli E2E tests")
    74→	}
    75→	return nil
    76→}
    77→
    78→func (a *CursorCLI) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
    79→	cfg := &runConfig{}
    80→	for _, o := range opts {
    81→		o(cfg)
    82→	}
    83→
    84→	// Per-prompt timeout so a slow response gets killed early enough to
    85→	// retry within the test's overall budget.
    86→	timeout := 90 * time.Second
    87→	if cfg.PromptTimeout > 0 {
    88→		timeout = cfg.PromptTimeout
    89→	}
    90→	promptCtx, cancel := context.WithTimeout(ctx, timeout)
    91→	defer cancel()
    92→
    93→	args := []string{"-p", prompt, "--force", "--trust", "--workspace", dir}
    94→	displayArgs := []string{"-p", fmt.Sprintf("%q", prompt), "--force", "--trust", "--workspace", dir}
    95→
    96→	if cfg.Model != "" {
    97→		args = append(args, "--model", cfg.Model)
    98→		displayArgs = append(displayArgs, "--model", cfg.Model)
    99→	}
   100→
   101→	cmd := exec.CommandContext(promptCtx, a.Binary(), args...)
   102→	cmd.Dir = dir
   103→	cmd.Stdin = nil
   104→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
   105→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
   106→	cmd.Cancel = func() error {
   107→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
   108→	}
   109→	cmd.WaitDelay = 5 * time.Second
   110→
   111→	var stdout, stderr strings.Builder
   112→	cmd.Stdout = &stdout
   113→	cmd.Stderr = &stderr
   114→
   115→	err := cmd.Run()
   116→	exitCode := 0
   117→	if err != nil {
   118→		exitErr := &exec.ExitError{}
   119→		if errors.As(err, &exitErr) {
   120→			exitCode = exitErr.ExitCode()
   121→		} else {
   122→			exitCode = -1
   123→		}
   124→		// Wrap the prompt-level deadline so IsTransientError can detect it.
   125→		if promptCtx.Err() == context.DeadlineExceeded {
   126→			err = fmt.Errorf("%w: %w", err, context.DeadlineExceeded)
   127→		}
   128→	}
   129→
   130→	return Output{
   131→		Command:  a.Binary() + " " + strings.Join(displayArgs, " "),
   132→		Stdout:   stdout.String(),
   133→		Stderr:   stderr.String(),
   134→		ExitCode: exitCode,
   135→	}, err
   136→}
   137→
   138→func (a *CursorCLI) StartSession(ctx context.Context, dir string) (Session, error) {
   139→	name := fmt.Sprintf("cursor-cli-test-%d", time.Now().UnixNano())
   140→	s, err := NewTmuxSession(name, dir, nil, a.Binary(), "--force", "--workspace", dir)
   141→	if err != nil {
   142→		return nil, err
   143→	}
   144→
   145→	// Wait for the TUI to be ready (input prompt).
   146→	if _, err := s.WaitFor(`>`, 30*time.Second); err != nil {
   147→		_ = s.Close()
   148→		return nil, fmt.Errorf("waiting for startup prompt: %w", err)
   149→	}
   150→	s.stableAtSend = ""
   151→
   152→	return s, nil
   153→}
