    88→func (c *CursorAgent) parseTurnStart(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
    89→	raw, err := agent.ReadAndParseHookInput[beforeSubmitPromptInputRaw](stdin)
    90→	if err != nil {
    91→		return nil, err
    92→	}
    93→	return &agent.Event{
    94→		Type:       agent.TurnStart,
    95→		SessionID:  raw.ConversationID,
    96→		SessionRef: c.resolveTranscriptRef(ctx, raw.ConversationID, raw.TranscriptPath),
    97→		Prompt:     raw.Prompt,
    98→		Timestamp:  time.Now(),
    99→	}, nil
   100→}
