    32→// HooksFileName is the hooks file used by Cursor.
    33→const HooksFileName = "hooks.json"
    34→
    35→// entireHookPrefixes are command prefixes that identify Entire hooks
    36→var entireHookPrefixes = []string{
    37→	"entire ",
    38→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
    39→}
    40→
    41→// HookNames returns the hook verbs Cursor supports.
    42→// These become subcommands: entire hooks cursor <verb>
    43→func (c *CursorAgent) HookNames() []string {
    44→	return []string{
    45→		HookNameSessionStart,
    46→		HookNameSessionEnd,
    47→		HookNameBeforeSubmitPrompt,
