   305→// GetSupportedHooks returns the hook types Cursor supports.
   306→func (c *CursorAgent) GetSupportedHooks() []agent.HookType {
   307→	return []agent.HookType{
   308→		agent.HookSessionStart,
   309→		agent.HookSessionEnd,
   310→		agent.HookUserPromptSubmit,
   311→		agent.HookStop,
   312→		agent.HookPreToolUse,
   313→		agent.HookPostToolUse,
   314→	}
   315→}
   316→
   317→// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
   318→// Silently ignores parse errors (leaves target unchanged).
   319→func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
   320→	if data, ok := rawHooks[hookType]; ok {
   321→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
   322→		json.Unmarshal(data, target)
   323→	}
   324→}
   325→
   326→// marshalCursorHookType marshals a hook type back into rawHooks.
   327→// If the slice is empty, removes the key from rawHooks.
   328→func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
   329→	if len(entries) == 0 {
   330→		delete(rawHooks, hookType)
   331→		return
   332→	}
   333→	data, err := json.Marshal(entries)
   334→	if err != nil {
   335→		return // Silently ignore marshal errors (shouldn't happen)
   336→	}
   337→	rawHooks[hookType] = data
   338→}
   339→
   340→// Helper functions for hook management
   341→
   342→func hookCommandExists(entries []CursorHookEntry, command string) bool {
   343→	for _, entry := range entries {
   344→		if entry.Command == command {
   345→			return true
   346→		}
   347→	}
   348→	return false
   349→}
   350→
   351→func isEntireHook(command string) bool {
   352→	for _, prefix := range entireHookPrefixes {
   353→		if strings.HasPrefix(command, prefix) {
   354→			return true
   355→		}
   356→	}
   357→	return false
   358→}
   359→
   360→func hasEntireHook(entries []CursorHookEntry) bool {
   361→	for _, entry := range entries {
   362→		if isEntireHook(entry.Command) {
   363→			return true
   364→		}
   365→	}
   366→	return false
   367→}
   368→
   369→func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
   370→	result := make([]CursorHookEntry, 0, len(entries))
   371→	for _, entry := range entries {
   372→		if !isEntireHook(entry.Command) {
   373→			result = append(result, entry)
   374→		}
   375→	}
   376→	return result
   377→}
