   687→func initGitRepo(t *testing.T, dir string) {
   688→	t.Helper()
   689→	gitDir := filepath.Join(dir, ".git")
   690→	if err := os.MkdirAll(gitDir, 0o755); err != nil {
   691→		t.Fatalf("failed to create .git: %v", err)
