    31→// SetupRepo creates a fresh git repository in a temporary directory, seeds it
    32→// with an initial commit, and runs `entire enable` for the given agent.
    33→// Artifact capture is registered as a cleanup function.
    34→//
    35→// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
    36→// so it can be inspected after the test. A symlink in the artifact dir
    37→// points to the preserved repo.
    38→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
    39→	t.Helper()
    40→
    41→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
    42→
    43→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
    44→	// creates nested subdirectories (TestName.../001/) whose structure
    45→	// confuses some agents' (e.g. opencode) working-directory resolution.
    46→	dir, err := os.MkdirTemp("", "e2e-repo-*")
    47→	if err != nil {
    48→		t.Fatalf("create temp dir: %v", err)
    49→	}
    50→	if keepRepos {
    51→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
    52→	} else {
    53→		t.Cleanup(func() { os.RemoveAll(dir) })
    54→	}
    55→
    56→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
    57→	// what agent CLIs see when they resolve their own CWD.
    58→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
    59→		dir = resolved
    60→	}
    61→
    62→	Git(t, dir, "init")
    63→	Git(t, dir, "config", "user.name", "E2E Test")
    64→	Git(t, dir, "config", "user.email", "e2e@test.local")
    65→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
    66→
    67→	entire.Enable(t, dir, agent.EntireAgent())
    68→	PatchSettings(t, dir, map[string]any{"log_level": "debug"})
    69→
    70→	// OpenCode's non-interactive mode auto-rejects external_directory permission
    71→	// since there's no user to prompt. Write a config to allow it.
    72→	if agent.Name() == "opencode" {
    73→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
    74→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
    75→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
    76→		}
    77→		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
    78→			t.Fatalf("write opencode.json: %v", err)
    79→		}
    80→	}
    81→
    82→	// Create artifact dir eagerly so console.log is written to disk
    83→	// incrementally. Even if the test is killed by a global timeout,
    84→	// partial output survives.
    85→	artDir := artifactDir(t)
    86→	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
    87→	if err != nil {
    88→		t.Fatalf("create console.log: %v", err)
    89→	}
    90→
    91→	state := &RepoState{
    92→		Agent:            agent,
    93→		Dir:              dir,
    94→		ArtifactDir:      artDir,
    95→		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
    96→		CheckpointBefore: GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1"),
    97→		ConsoleLog:       consoleLog,
    98→	}
    99→
   100→	t.Cleanup(func() {
   101→		_ = consoleLog.Close()
   102→		if !state.skipArtifacts {
   103→			CaptureArtifacts(t, state)
   104→		}
   105→	})
   106→
   107→	return state
   108→}
